      "answer": "防止传变，是指在掌握疾病的发生发展规律及其传变途径的基础上，早期诊断与治疗以防止疾病的发展。防止传变包括阻截病传途径与先安未受邪之地两个方面。①阻截病传途径：疾病一般都有其一定的传变规律和途径。如伤寒病的六经传变，病初多在肌表的太阳经，病变发展则易往他经传变，因此，太阳病阶段就是伤寒病早期诊治的关键，在此阶段的正确有效的治疗，是防止伤寒病病势发雇的最好措施；又如温病多始于卫分证，因此，卫分证阶段就是温病早期诊治的关键。据此可知，邪气侵犯人体后，就要根据其传变规律，早期诊治，阻截其病传途径，以防止疾病的深化与恶化。②先安未受邪之地：可以五行的生克乘侮规律、五脏的整体规律、经络相传规律为指导。如脏腑有病，可由病变性质差异而有及子、犯母、相乘、相侮等传变。因此，根据不同病变的传变规律，实施预防性治疗，当可控制其病理传变。如《金匮要略•脏腑经络先后病脉证第一》所说：“见肝之病， 知肝传脾，当先实脾。”又如温热病伤及胃阴时，其病变发展趋势将易耗及肾阴，清代医家叶天士据此提出了“务在先安未受邪之地”的防治原则，主张在甘寒以养胃阴的方药中，加入咸寒滋肾阴的药物，以防止肾阴的耗损。这些都是既病防变原则的有效应用。"
