      "answer": "（1）调气包括补气与调理气机两部分内容：①补气：用于较单纯的气虚证。由于气的生成来源于肾之先天之精所化的元气、脾胃化生的水谷之精所化的谷气以及由肺吸入的自然界的清气，因此，补气多为补益肺、脾、肾。又由于卫气、营气、元气与宗气的化生或充养多与脾胃化生的谷气有关，故尤为重视对脾气的补益。②调理气机：用于气机失调的病证。气机失调的病机主要有气滞、气逆、气陷、气闭、气脱等。治疗时气滞者宜行气，气逆者宜降气，气陷者宜补气升气，气闭者宜顺气开窍通闭，气脱者则宜益气固脱。（2）调血包括补血与调理血运两个方面：①补血：用于血虚证。由于血虚证主要见于肝、心两脏，故补血法主要用于肝血虚证和心血虚证。又因血的生成与脾胃、肾等脏腑机能密切相关，因此补血时，应注意同时调治这些脏腑的机能。其中又因“脾胃为后天之本”，“气血生化之源”，故尤为重视对脾胃的补养。②调理血运：血运失常的病变主要有血瘀、出血等，而血寒是血瘀的主要病机；血热、气虚、瘀血是出血的主要病机。治疗时，血瘀者宜活血化瘀；因血寒而瘀者宜温经散寒行血；出血者宜止血，且须据出血的不同病机而施以清热、补气、活血等法。"
