      "title": "20.试述火热内生的主要病因病机。",
      "chooses": [],
      "answer": "阴阳偏胜，是指阴阳双方中某一方 的病理性亢盛状态，属于“邪气盛则实” 的实证病机。阳偏胜，是指机体在疾病过程中所出现 的一种阳气病理性偏盛、机能亢奋、机体反 应性增强、热量过剩的病理状态。一般而 言，其病机特点多表现为阳盛而阴未虚的实 热证。形成阳偏胜的主要原因，多由于感受 温热阳邪，或虽感受阴邪，但从阳化热，也 可由于情志内伤，五志过极而化火，或因气 滞、血瘀、食积等郁而化热所致。阳气的病理性亢盛，以热、动、燥为其 特点，故阳气偏胜可见壮热、烦渴、面红、 目赤、尿黄、便干、苔黄、脉数等症。阳热 亢盛则对阴气和津液的制约太过，所以说 “阳胜则阴病”，即阳盛则耗伤阴气和津液。 阳盛之初，对津液和阴气的损伤不明显，从 而出现实热证。如果病情发展，阳热亢盛且明显耗伤机体的津液和阴气，病则从实热证 转化为实热兼阴虚津亏证，若阴气大伤，病 可由实转虚而发展为虚热证。阴偏胜，是指机体在疾病过程中所出现 的一种阴气病理性偏盛、机能抑制、热量耗 伤过多的病理状态。一般而言，其病机特点 多表现为阴盛而阳未虚的实寒证。形成阴偏 胜的主要原因，多由于感受寒湿阴邪，或过 食生冷，寒邪中阻等，导致体内阴气的病理 性几盛的阴气的病理性亢盛，以寒、静、湿为其 特点，如形寒、肢冷、蜷卧、舌淡而润、脉 迟等，即是阴气偏胜的具体表现。阴气亢盛 则过度制约阳气，所以说“阴胜则阳病”， 即阴盛则损伤阳气而致阳虚。由于阴气内盛 多伤阳气，故在阴偏胜时，常同时伴有程度 不同的阳气不足，形成实寒兼阳虚证；若阳 气伤甚，病可由实转虚，发展为虚寒证。"
