      "answer": "气滞血瘀、气虚血瘀、气不摄血、气随血脱以及气 血两虚等几方面。气滞血瘀，是指因气的运行郁滞不畅， 以至;血液运行障碍，继而出现血瘀的病理状 态：多因情志内伤，抑郁不遂，气机阻滞， 而致血瘀，多与肝失疏泄密切相关。临床上 常见胸胁胀满疼痛、瘕聚、癥积#证。气虚血瘀，是指因气对血^动无力而 致血行不畅，甚至瘀阻不行的^理状态，多 见于心气不足、运血无力而致的惊悸怔忡、 喘促、水肿及气虚血滞的肢体瘫痪、痿废。 气虚和气滞可与血瘀并存，三者相互影响。气不摄血，是指由于气虚不足，统摄血 液的功能减弱，血不循经，逸出脉外，而导 致各种出血的病理状态。由于脾主统血，故 气不摄血的病变，主要表现为中气不足、气 不摄血的咯血、吐血、紫斑、便血、崩漏等 症，同时见面色不华、脉虚无力、舌淡等气 虚征象。气随血脱，是指在大量出血的同时，气 也随着血液的流失而急剧散脱，从而形成气 血并脱的危重病理状态。这是因为血为气之 载体，血脱，则气失去依附，故气亦随之散 脱而亡失。症见精神萎靡、眩晕或晕厥、冷 汗淋漓、四末不温，或有抽搐，或见口干， ‘脉微细。气血两虚，即气虚和血虚同时存在的病 理状态。多因久病消耗，气血两伤，或先有 失血，气随血耗，或先因气虚，化血衰少， 从而形成气血两虚。临床上可见面色淡白或 '萎黄、少气懒言、疲乏无力、形体瘦削、心 悸失眠、肌肤干燥、肢体麻木等症。"
