      "answer": "火热内生，是指由于阳盛有余，或 阴虚阳亢，或由于气血郁滞，或由于病邪郁 结，而产生的火热内扰，机能亢奋的病理状 态。火热内生有虚实之分，其病机主要有如下几方面：①阳气过盛化火：人身之阳气在正常的 情况下，有温煦脏腑组织之作用，中医学称 之为“少火”。但是在病理情况下，阳气过 盛，机能亢奋，必然使物质的消耗增加，以 致伤阴耗液。此种病理性的阳气过亢则称为 “壮火”。②邪郁化火：一是外感六淫风、寒、 燥、湿等病邪，在病理过程中，皆能郁滞从 阳而化热化火。二是体内的病理性产物 (如痰、瘀等）和食积、虫积等，亦能郁而 化火。邪郁化火的主要机理，是由于这些因 素导致机体阳气的郁滞，气郁则生热化火。③五志过极化火：多指由于情志的刺 激，影响了机体气血、阴阳和脏腑的协调平 衡，造成气机郁结，久则从阳而化热，因之 火热内生。如情志内伤，抑郁不畅，则常能 导致肝郁气滞，气郁化火，发为“肝火”。④阴虚火旺：此属虚火，多由于阴气大 伤，阴虚阳亢，则虚热虚火内生。阴虚火 旺，往往指较集中于机体的某一部位的虚火 证候。如阴虚而引起的牙痛、齿衄、咽痛、 颧红等，皆为虚火上炎所致。"
