    {
      "type": 6,
      "title": "23.试分析“因人制宜”的涵义，并举例说明之。",
      "chooses": [],
      "answer": "影响疾病传变的因素有体质因素、 病邪因素、地域因素、气候因素和生活因素等。①体质因素：体质主要从两方面对疾病的传变发生作用。一是在较大程度上影响正 气之强弱，从而影响发病与传变的迟速。如 素体盛者，一般不易感受病邪，一旦感邪则 发病急速，但传变较少，病程亦较短暂；素 体虚者，则易于感邪，且易深人，病势较 缓，病程缠绵而多传变。二是在邪正相争过 程中，对病邪的“从化”具有重要的决定 作用。一般而论，素体阳盛者，则邪多从火 化，疾病多向阳热实证演变；素体阴盛者， 则邪多从寒化，疾病多向实寒或虚寒等证演变。②病邪因素：首先，传变的迟速与邪气 的性质直接相关。如外感六淫病邪，一般阳 邪传变较快，阴邪传变较慢；疠气则传变急 速；湿、痰、水饮及瘀血内生，传变一般迟于外邪。另外，邪盛则传变较快，邪微则传 变缓慢。其次，各种不同的病邪，其伤人的 途径不同，病位传变的路径亦有较大的差 异。外感病因以表里传变为主，内伤病因主 要是脏腑传变，亦可表里相及。③地域因素：一般来说，地域因素的长 期作用，形成不同地理环境人群的体质特征 和疾病谱的差异，同时亦影响疾病的传变 比如，居处高燥地域的人群，感邪后较易化 热、化燥，伤阴耗津；而居处卑湿之地者， 病变较易化湿，伤气伤阳。④气候因素：不同的时令气候，可影响 疾病的传变。如冬春寒冷季节，寒哮一证， 容易出现外寒入里引动内饮而发病，发生表 里的传变；而阳盛之躯，则可因寒邪外束腠 理，阳气不得发越而暴亢，乃至化火生风， 发生厥仆之变。⑤生活因素：主要包括情志、饮食、劳 逸等，其中情志因素对七情内伤所致疾病的 影响最大，并通过干扰气机，影响气血阴阳 而对疾病传变发生作用。饮食与脾胃、胆、 大、小肠病证传变的关系尤为密切，且通过 对水谷运化、气血生化的影响而对疾病传变 发生作用。过劳耗伤人体正气而影响外感和 内伤疾病的传变甚为常见，而过逸则气虚运 行不畅、气化衰弱而影响疾病传变。防治原则"
    },
    {
      "type": 6,
      "title": "24.试述调整阴阳中“补其不足”的用法。",
      "chooses": [],
      "answer": "（1）“本”和“标”是相对而言的，标本常用来概括说明事物的现象与本质，在中医学中常用来概括病变过程中矛盾的主次先后关系。本是事物的主要矛盾，标是事物的次要矛盾。标本是随着疾病发展变化的具体情况所指有所不同。如就邪正而言，正气为本，邪气为标；就病机与症状而言，病机为本，症状是标，就疾病先后而言，旧病、原发病为本，新病、继发病是标，等等。（2）在复杂多变的病证中，或在疾病的危重阶段，就必须治标治本的缓急先后。①缓则治本：缓则治其本，多用在病情缓和，病势迁延，暂无急重病状的情况下。此时必须着眼于疾病本质的治疗。如痨病肺肾阴虚之咳嗽，肺肾阴虚是本，咳嗽是标。故治疗不用单纯止咳法来治标，而应滋养肺肾以治本，本病得愈，咳嗽也自然会消除。②急则治标：病证急重时的标本取舍原则是标病急重，则当先治、急治其标。如大出血病人，由于大出血会危及生命，故不论何种原因的出血，均应紧急止血以治标，待血止，病情缓和后再治其病本。③标本兼治：当标本错杂并重时采取的一种治则。若采取单治本病或单治标病方法，均不能适应病证治疗要求时，则须标本兼顾同治，才能获得好的治疗效果。如在热性病过程中，热盛伤津耗阴，邪热里结为本，津液与阴气受伤为标，治当泻热攻下与滋阴增液通便同用。"
    }
